&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:2046052,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:300,&amp;quot;335559991&amp;quot;:190,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Apply structured PACCT qualification frameworks to assess fit, readiness and urgency.&lt;/span&gt;&lt;/li&gt;
